package com.example.takura.media.application;
import java.sql.Timestamp;import java.time.Clock;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;
@Component public class StorageMaintenanceWorker {private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final ObjectStoragePort storage;private final Clock clock;public StorageMaintenanceWorker(JdbcTemplate jdbc,TransactionTemplate tx,ObjectStoragePort storage,Clock clock){this.jdbc=jdbc;this.tx=tx;this.storage=storage;this.clock=clock;}
 public int cleanupOnce(){var row=tx.execute(s->{var rows=jdbc.query("SELECT id,staging_key,staging_version,private_key,private_version FROM takura.attachment WHERE enquiry_id IS NULL AND cleanup_eligible_at<=? AND state NOT IN ('DELETION_PENDING','DELETED') ORDER BY cleanup_eligible_at FOR UPDATE SKIP LOCKED LIMIT 1",(rs,n)->new Item((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5)),Timestamp.from(clock.instant()));if(rows.isEmpty())return null;var item=rows.getFirst();jdbc.update("UPDATE takura.attachment SET state='DELETION_PENDING',revision=revision+1 WHERE id=?",item.id());return item;});if(row==null)return 0;try{if(row.stagingKey()!=null)storage.deleteStaging(row.stagingKey(),row.stagingVersion());if(row.privateKey()!=null)storage.deletePrivate(row.privateKey(),row.privateVersion());jdbc.update("UPDATE takura.attachment SET state='DELETED',revision=revision+1 WHERE id=? AND state='DELETION_PENDING'",row.id());audit(row.id(),"ABANDONED_DELETE","COMPLETED");}catch(RuntimeException retry){audit(row.id(),"ABANDONED_DELETE","RETRY");}return 1;}
 public int reconcileOnce(){var rows=jdbc.query("SELECT id,private_key,private_version FROM takura.attachment WHERE state='CLEAN' AND private_key IS NOT NULL ORDER BY scan_completed_at LIMIT 100",(rs,n)->new Item((UUID)rs.getObject(1),null,null,rs.getString(2),rs.getString(3)));int missing=0;for(var row:rows)if(!storage.privateExists(row.privateKey(),row.privateVersion())){missing++;audit(row.id(),"REFERENCE_RECONCILIATION","MISSING_PRIVATE_OBJECT");}return missing;}
 private void audit(UUID attachment,String action,String outcome){jdbc.update("INSERT INTO takura.storage_audit_event(id,attachment_id,action,outcome,occurred_at) VALUES(?,?,?,?,?)",UUID.randomUUID(),attachment,action,outcome,Timestamp.from(clock.instant()));}private record Item(UUID id,String stagingKey,String stagingVersion,String privateKey,String privateVersion){}
}
